mapper.sql:
${limitBefore} select distinct RES.ID_ "taskId", RES.EXECUTION_ID_ "executionId", RES.PROC_INST_ID_ "processInstanceId", RES.PROC_DEF_ID_ "processDefinitionId", RES.NAME_ "activityName", RES.DESCRIPTION_ "description" , RES.TASK_DEF_KEY_ "activityId", RES.CREATE_TIME_ "createTime", ht.claim_time_ "claimTime", RES.DUE_DATE_ "dueDate", RES.SUSPENSION_STATE_ "suspensionState", RES.FORM_KEY_ "formKey", RES.TENANT_ID_ "tenantId", E.BUSINESS_KEY_ "businessKey", ahp.START_USER_ID_ "startUserId", ahp.START_TIME_ "processStartTime", ahp.SUPER_PROCESS_INSTANCE_ID_ "superProcessInstanceId", arv.TEXT_ "orgId", rv.TEXT_ "taskType", R.NAME_ "processDefineName", R.KEY_ "processDefineKey", C.name "classifyName", C.code "classifyCode", RES.ASSIGNEE_ "assignee"
,
${field}
${limitBetween}
ORDER BY RES.CREATE_TIME_ DESC
ORDER BY RES.CREATE_TIME_ ASC
${limitAfter}

FROM ${prefix}act_ru_task RES
INNER JOIN wf_task_expand_data w ON RES.ID_ = w.task_id
AND RES.PROC_INST_ID_ = W.PROCESS_INST_ID

    LEFT JOIN ACT_RU_IDENTITYLINK I ON I.TASK_ID_ = RES.ID_


        AND I.USER_ID_ = #{userId}


LEFT JOIN ACT_RU_EXECUTION E ON RES.PROC_INST_ID_ = E.PROC_INST_ID_ AND E.PARENT_ID_ IS NULL
LEFT JOIN ACT_RE_PROCDEF R ON RES.PROC_DEF_ID_ = R.ID_

LEFT JOIN WF_PROCESS_CLASSIFY C ON C.id = R.CATEGORY_
LEFT JOIN ACT_HI_PROCINST ahp ON ahp.PROC_INST_ID_ = RES.PROC_INST_ID_
LEFT JOIN act_ru_variable arv ON arv.PROC_INST_ID_ = RES.PROC_INST_ID_
AND arv.NAME_='_START_USER_ORG_ID'
LEFT JOIN act_ru_variable rv ON rv.TASK_ID_ = RES.ID_
AND rv.NAME_='_ADDED_TASK_TYPE'

    INNER JOIN (
    SELECT HIPOOL.* FROM WF_HI_TASK_POOL_EXECUTE_DATA HIPOOL
    INNER JOIN
    (SELECT
    INHIPOOL.TASK_ID_,MAX(INHIPOOL.CREATE_DATE_) AS MAX_DATE
    FROM
    WF_HI_TASK_POOL_EXECUTE_DATA INHIPOOL
    GROUP BY
    INHIPOOL.TASK_ID_
    ) OUTHIPOOL
    ON
    HIPOOL.TASK_ID_ = OUTHIPOOL.TASK_ID_ AND HIPOOL.CREATE_DATE_ = OUTHIPOOL.MAX_DATE AND HIPOOL.IS_ALLOT_ = '1'
    ) HIPOOLS ON HIPOOLS.TASK_ID_ = RES.ID_


INNER JOIN act_hi_taskinst ht on RES.id_ = ht.id_




            AND ${condition}



        AND ahp.START_TIME_ BETWEEN #{processCreateTimeBefore} AND #{processCreateTimeAfter}


        AND ahp.START_TIME_ BETWEEN to_date(#{processCreateTimeBefore},'yy-mm-dd,hh24:mi:ss') AND to_date(#{processCreateTimeAfter},'yy-mm-dd,hh24:mi:ss')


        AND RES.PROC_INST_ID_ = #{processInstanceId}


        AND RES.PROC_DEF_ID_ = #{processDefinitionId}


        AND RES.TASK_DEF_KEY_ = #{taskDefinitionKey}


        AND RES.ID_ = #{taskId}


        AND RES.NAME_ LIKE #{taskNameLike}


        AND RES.TENANT_ID_ = #{tenantId}


        AND RES.TENANT_ID_ IN

            #{tenantId}



        AND C.code = #{classifyCode}


        AND ht.claim_time_  < #{claimTimeBefore}


        AND ht.claim_time_  > #{claimTimeAfter}


        AND E.BUSINESS_KEY_ = #{businessKey}


        AND E.BUSINESS_KEY_ like #{businessKeyLike}


        AND  R.NAME_ = #{processDefineName}


        AND  R.NAME_ like #{processDefineNameLike}


        AND  R.KEY_ = #{processDefineKey}


        AND  R.KEY_ like #{processDefineKeyLike}



            AND RES.CREATE_TIME_ <= to_timestamp(#{createTimeBefore}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')


            AND RES.CREATE_TIME_ >= to_timestamp(#{createTimeAfter}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')




            AND RES.CREATE_TIME_ <= #{createTimeBefore}


            AND RES.CREATE_TIME_ >= #{createTimeAfter}



        AND  RES.TASK_DEF_KEY_ != #{unequalActivityId}


        AND  RES.NAME_ != #{unequalActivityName}

mapper.select:
SELECT c.userId, COUNT(c.taskId) taskCount FROM ( SELECT USER_ID_ userId, TASK_ID_ taskId FROM act_ru_identitylink t, act_ru_task t1 WHERE t.TYPE_ = 'candidate' AND t.task_id_ = t1.id_ AND t.USER_ID_ IS NOT NULL AND t1.assignee_ IS NULL UNION SELECT ASSIGNEE_ userId, ID_ taskId FROM act_ru_task WHERE ASSIGNEE_ IS NOT NULL AND ASSIGNEE_ != '' AND ASSIGNEE_ != 'rebackSetNull' ) c
c.userId = #{userId}
GROUP BY c.userId

mapper.sql:
FROM ${prefix}act_ru_task RES
INNER JOIN wf_task_expand_data w ON RES.ID_ = w.task_id



    LEFT JOIN ACT_RU_IDENTITYLINK I ON I.TASK_ID_ = RES.ID_
    AND I.USER_ID_ = #{userId}


    LEFT JOIN ACT_RU_IDENTITYLINK I ON I.TASK_ID_ = RES.ID_


    INNER JOIN act_hi_taskinst ht on RES.id_ = ht.id_

        and ht.ASSIGNEE_= #{userId}




    INNER JOIN WF_HI_TASK_POOL_EXECUTE_DATA hp
    ON RES.id_ = hp.TASK_ID_ and RES.ASSIGNEE_ = hp.user_id_ and hp.sys_id_ = #{userId}





        AND RES.PROC_INST_ID_ = #{processInstanceId}


        AND RES.PROC_DEF_ID_ = #{processDefinitionId}


        AND RES.TASK_DEF_KEY_ = #{taskDefinitionKey}


        AND R.KEY_ in

            #{processDefineKey}



        AND RES.ID_ = #{taskId}



        AND RES.NAME_ LIKE #{taskNameLike}



        AND RES.TENANT_ID_ = #{tenantId}



        AND RES.TENANT_ID_ IN

            #{tenantId}





        AND (
        RES.ASSIGNEE_ = #{userId}
        OR (
        RES.ASSIGNEE_ IS NULL
        AND (
        I.USER_ID_ = #{userId}
        )
        )
        )


        AND RES.ASSIGNEE_ is null
        AND I.TYPE_ = 'candidate'
        AND I.GROUP_ID_ IN

            #{role}



        AND RES.ASSIGNEE_ is null
        AND I.TYPE_ = 'candidateOrgs'
        AND I.GROUP_ID_ IN

            #{org}




        AND RES.ASSIGNEE_ IS NOT NULL


        AND RES.ASSIGNEE_ = #{userId}


        AND I.USER_ID_ is NOT NULL AND RES.ASSIGNEE_ IS NULL


        AND I.USER_ID_ = #{userId}


        AND RES.ASSIGNEE_ = #{userId}



            AND ht.claim_time_  < #{claimTimeBefore}


            AND ht.claim_time_  > #{claimTimeAfter}




            AND RES.CREATE_TIME_ <= to_timestamp(#{createTimeBefore}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')


            AND RES.CREATE_TIME_ >= to_timestamp(#{createTimeAfter}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')




            AND RES.CREATE_TIME_ <= #{createTimeBefore}


            AND RES.CREATE_TIME_ >= #{createTimeAfter}



        AND  RES.TASK_DEF_KEY_ != #{unequalActivityId}


        AND  RES.NAME_ != #{unequalActivityName}

mapper.select:
${limitBefore}
select RES.*, row_number() over (ORDER BY RES."taskId" ) rnk FROM (
SELECT distinct RES.ID_ "taskId", RES.EXECUTION_ID_ "executionId", RES.PROC_INST_ID_ "processInstanceId", RES.PROC_DEF_ID_ "processDefinitionId", RES.NAME_ "activityName", RES.DESCRIPTION_ "description", RES.TASK_DEF_KEY_ "activityId", RES.CREATE_TIME_ "createTime", RES.DUE_DATE_ "dueDate", RES.SUSPENSION_STATE_ "suspensionState", RES.TENANT_ID_ "tenantId", RES.ASSIGNEE_ "assignee", W.BUSINESS_KEY "businessKey", W.START_USER_ID "startUserId", W.START_USER_NAME "startUserName", W.PROCESS_START_TIME "processStartTime", W.SUPER_PROCESS_INSTANCE_ID "superProcessInstanceId", W.START_USER_ORG_CODE "startUserOrgCode", W.PROCESS_NAME "processDefineName", W.PROCESS_DEF_KEY "processDefineKey", W.PROCESS_CLASSIFY_CODE "classifyCode", W.ACT_BUTTON "actButton", W.IS_MULTI "isMulti", W.CANDIDATE_ROLES "candidateRoles", W.CANDIDATE_DEPTS "candidateDepts", W.CANDIDATE_ORGS "candidateOrgs", W.SELECT_USER_MODEL "selectUserModel", W.IS_START_NODE "isStartNode", W.task_Type "taskType", W.FORM_SCENE "formScene", '1' AS "taskStatus"
,
${field}
ORDER BY RES.CREATE_TIME_ DESC
ORDER BY RES.CREATE_TIME_ ASC
${limitAfter}

mapper.sql:
FROM ${prefix}act_ru_task RES
INNER JOIN wf_task_expand_data w ON RES.ID_ = w.task_id
LEFT JOIN ACT_RU_IDENTITYLINK I ON I.TASK_ID_ = RES.ID_



        AND RES.PROC_INST_ID_ = #{processInstanceId}


        AND RES.PROC_DEF_ID_ = #{processDefinitionId}



            and RES.ASSIGNEE_  is not null

                AND RES.ASSIGNEE_=#{assignee}



            and RES.ASSIGNEE_  is null



        AND RES.TASK_DEF_KEY_ = #{taskDefinitionKey}


        AND R.KEY_ in

            #{processDefineKey}



        AND RES.ID_ = #{taskId}



        AND RES.NAME_ LIKE #{taskNameLike}





        AND RES.TENANT_ID_ = #{tenantId}




        AND w.START_USER_ID = #{startUserId}



        AND w.START_USER_NAME like #{startUserName}



        AND w.START_USER_ORG_CODE like #{startUserOrgCode}



        AND RES.TENANT_ID_ IN

            #{tenantId}




            AND (


                    I.TYPE_ = #{postInfo.type} and I.USER_ID_ = #{postInfo.userId}


                    I.TYPE_ = #{postInfo.type} and I.ROLE_CODE = #{postInfo.roleCode}


                    I.TYPE_ = #{postInfo.type} and I.ORG_CODE = #{postInfo.orgCode}


                    I.TYPE_ = #{postInfo.type} and I.DEPT_CODE = #{postInfo.deptCode}


                    I.TYPE_ = #{postInfo.type} and I.ROLE_CODE = #{postInfo.roleCode}

                        and I.ORG_CODE = #{postInfo.orgCode}


                        and I.ORG_CODE is null


                        and I.DEPT_CODE = #{postInfo.deptCode}


                        and I.DEPT_CODE is null



                    I.TYPE_ = #{postInfo.type}

                        and I.GROUP_ID_ = #{postInfo.groupId}


                        and I.ORG_CODE = #{postInfo.orgCode}


                        and I.ROLE_CODE = #{postInfo.roleCode}


                        and I.DEPT_CODE = #{postInfo.deptCode}



            )


            and I.TYPE_ = null







            AND RES.CREATE_TIME_ <= to_timestamp(#{createTimeBefore}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')


            AND RES.CREATE_TIME_ >= to_timestamp(#{createTimeAfter}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')

        AND  NVL(I.due_date,to_date('2999-01-01','yyyy-MM-dd')) >= sysdate



            AND RES.CREATE_TIME_ <= #{createTimeBefore}


            AND RES.CREATE_TIME_ >= #{createTimeAfter}



        AND  RES.TASK_DEF_KEY_ != #{unequalActivityId}


        AND  RES.NAME_ != #{unequalActivityName}

FROM act_hi_taskinst hi
left join ${prefix}act_ru_task RES on res.id_ = hi.id_ AND RES.TENANT_ID_ = #{tenantId}
left JOIN wf_task_expand_data w ON RES.ID_ = w.task_id AND w.TENANT_ID = #{tenantId}
LEFT JOIN ACT_RU_IDENTITYLINK I ON I.TASK_ID_ = RES.ID_



        AND RES.PROC_INST_ID_ = #{processInstanceId}


        AND RES.PROC_DEF_ID_ = #{processDefinitionId}


        AND RES.TASK_DEF_KEY_ = #{taskDefinitionKey}


        AND R.KEY_ in

            #{processDefineKey}



        AND RES.ID_ = #{taskId}



        AND RES.NAME_ LIKE #{taskNameLike}



        AND w.START_USER_ID = #{startUserId}



        AND w.START_USER_NAME like #{startUserName}



        AND w.START_USER_ORG_CODE like #{startUserOrgCode}




            AND (


                    I.TYPE_ = #{postInfo.type} and I.USER_ID_ = #{postInfo.userId}


                    I.TYPE_ = #{postInfo.type} and I.ROLE_CODE = #{postInfo.roleCode}


                    I.TYPE_ = #{postInfo.type} and I.ORG_CODE = #{postInfo.orgCode}


                    I.TYPE_ = #{postInfo.type} and I.DEPT_CODE = #{postInfo.deptCode}


                    I.TYPE_ = #{postInfo.type} and I.ORG_CODE = #{postInfo.orgCode} and I.ROLE_CODE = #{postInfo.roleCode}


                    I.TYPE_ = #{postInfo.type}

                        and I.GROUP_ID_ = #{postInfo.groupId}


                        and I.ORG_CODE = #{postInfo.orgCode}


                        and I.ROLE_CODE = #{postInfo.roleCode}


                        and I.DEPT_CODE = #{postInfo.deptCode}



            )


            and I.TYPE_ = null







            AND RES.CREATE_TIME_ <= to_timestamp(#{createTimeBefore}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')


            AND RES.CREATE_TIME_ >= to_timestamp(#{createTimeAfter}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')


            AND hi.END_TIME_ <= to_timestamp(#{endTimeBefore}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')


            AND hi.END_TIME_ >= to_timestamp(#{endTimeAfter}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')

        AND  NVL(I.due_date,to_date('2999-01-01','yyyy-MM-dd')) >= sysdate



            AND RES.CREATE_TIME_ <= #{createTimeBefore}


            AND RES.CREATE_TIME_ >= #{createTimeAfter}



        AND  RES.TASK_DEF_KEY_ != #{unequalActivityId}


        AND  RES.NAME_ != #{unequalActivityName}
